-- Function: public.fn_get_all_children
-- Backup generated on 2026-10-25 20:32:58

CREATE OR REPLACE FUNCTION public.fn_get_all_children(p_tenant_id uuid, p_organization_id uuid DEFAULT NULL::uuid)  RETURNS TABLE(id uuid, tenant_id uuid, first_name character varying, last_name character varying, date_of_birth date, classroom_id uuid, photo_url text, profile_completion_percentage integer, enrollment_status character varying, draft_data text, is_active boolean, created_at timestamp with time zone, updated_at timestamp with time zone)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT c.id, c.tenant_id, c.first_name, c.last_name, c.date_of_birth, c.classroom_id,             c.photo_url, c.profile_completion_percentage, c.enrollment_status, c.draft_data,             c.is_active, c.created_at, c.updated_at     FROM children c     LEFT JOIN classrooms cl ON c.classroom_id = cl.id AND c.tenant_id = cl.tenant_id     LEFT JOIN branches b ON cl.branch_id = b.id AND cl.tenant_id = b.tenant_id     WHERE c.tenant_id = p_tenant_id AND c.is_active = true       AND (p_organization_id IS NULL             OR b.organization_id = p_organization_id             OR EXISTS (                SELECT 1 FROM enrollments e                 JOIN branches eb ON e.branch_id = eb.id                 WHERE e.child_id = c.id AND eb.organization_id = p_organization_id            ))     ORDER BY c.first_name, c.last_name; END; $function$ ;
